import json

with open('output/solution.json', encoding='utf-8') as f:
    data = json.load(f)

# 1. Validate all span_texts are substrings of raw_reason_text
span_issues = 0
for r in data['records']:
    for s in r['normalized']:
        if s['span_text'] not in r['raw_reason_text']:
            span_issues += 1
            print(f'ISSUE: {s[\"segment_id\"]}: span_text \"{s[\"span_text\"][:80]}\"')
            print(f'  in raw: \"{r[\"raw_reason_text\"][:100]}\"')
print(f'\\nTotal span_text issues: {span_issues}')

# 2. Validate all pred_codes are from the correct codebook
import csv
valid_codes = {}
for pid in ['P1_POWER', 'P2_CTRL', 'P3_RF']:
    valid_codes[pid] = set()
    with open(f'data/codebook_{pid}.csv') as f:
        reader = csv.DictReader(f)
        for row in reader:
            valid_codes[pid].add(row['code'])

code_issues = 0
for r in data['records']:
    for s in r['normalized']:
        if s['pred_code'] != 'UNKNOWN':
            if s['pred_code'] not in valid_codes.get(r['product_id'], set()):
                code_issues += 1
                print(f'CODE ISSUE: {s[\"segment_id\"]}: code {s[\"pred_code\"]} not in {r[\"product_id\"]} codebook')

print(f'Total code issues: {code_issues}')

# 3. Validate pred_label matches codebook
label_issues = 0
code_to_label = {}
for pid in ['P1_POWER', 'P2_CTRL', 'P3_RF']:
    with open(f'data/codebook_{pid}.csv') as f:
        reader = csv.DictReader(f)
        for row in reader:
            code_to_label[row['code']] = row['standard_label']

for r in data['records']:
    for s in r['normalized']:
        if s['pred_code'] != 'UNKNOWN':
            expected = code_to_label.get(s['pred_code'], '')
            if s['pred_label'] != expected:
                label_issues += 1
                if label_issues <= 5:
                    print(f'LABEL ISSUE: {s[\"segment_id\"]}: got \"{s[\"pred_label\"]}\" expected \"{expected}\"')

print(f'Total label issues: {label_issues}')

# 4. Confidence separation check
unk_confs = [s['confidence'] for r in data['records'] for s in r['normalized'] if s['pred_code'] == 'UNKNOWN']
non_unk_confs = [s['confidence'] for r in data['records'] for s in r['normalized'] if s['pred_code'] != 'UNKNOWN']

print(f'\\nUNKNOWN confidence range: [{min(unk_confs):.2f}, {max(unk_confs):.2f}]')
print(f'Non-UNKNOWN confidence range: [{min(non_unk_confs):.2f}, {max(non_unk_confs):.2f}]')
print(f'Gap between max UNKNOWN and min non-UNKNOWN: {min(non_unk_confs) - max(unk_confs):.2f}')

# 5. segment_id uniqueness
all_sids = [s['segment_id'] for r in data['records'] for s in r['normalized']]
if len(all_sids) == len(set(all_sids)):
    print('\\nAll segment_ids are unique: PASS')
else:
    print(f'\\nDuplicate segment_ids found: FAIL')

# 6. Verify segment_id format
bad_sids = [sid for sid in all_sids if not sid.startswith('R') or '-S' not in sid]
print(f'Bad segment_id format count: {len(bad_sids)}')

print('\\n=== ALL VALIDATIONS COMPLETE ===')
